import Foundation
import Testing
@testable import UsageCore

/// The checked-in fixtures: synthetic rollouts (`mise run fixtures-zstd`)
/// compressed by the reference encoder at the settings the decoder must
/// handle, plus generated byte patterns.
enum ZstdFixture {
    struct Missing: Error { let name: String }

    static func data(_ name: String) throws -> Data {
        guard let url = Bundle.module.url(
            forResource: name, withExtension: nil, subdirectory: "Fixtures/zstd")
        else { throw Missing(name: name) }
        return try Data(contentsOf: url)
    }

    /// Decodes a whole stream, keeping the decoder's path counters.
    static func decode(
        _ data: Data, limits: ZstdLimits = .standard
    ) throws(ZstdError) -> (output: Data, stats: ZstdStats) {
        var decoder = ZstdDecoder(source: ByteSource(data: data), limits: limits)
        var output = Data()
        while let chunk = try decoder.next() { output.append(contentsOf: chunk) }
        return (output, decoder.stats)
    }

    /// The generator's LCG bytes (scripts/zstd-fixtures.sh `noise`).
    static func noise(count: Int, seed: UInt32) -> Data {
        var state = seed
        return Data((0..<count).map { _ in
            state = state &* 69069 &+ 1
            return UInt8(state >> 24)
        })
    }

    /// scripts/zstd-fixtures.sh `pattern_ab` / `pattern_z`, with awk's float
    /// arithmetic reproduced exactly.
    static func pattern(_ name: String) -> Data {
        var seed: UInt64 = 5
        var text = ""
        for _ in 0..<3000 {
            seed = (seed * 69069 + 1) % 4_294_967_296
            let fraction = Double(seed) / 4_294_967_296
            if name == "ab" {
                text += String(repeating: "ab", count: 2 + Int(fraction * 40)) + "c"
            } else {
                text += String(repeating: "a", count: 20 + Int(fraction * 8) * 7) + "Z"
            }
        }
        return Data(text.utf8)
    }

    static let runs = Data(repeating: UInt8(ascii: "a"), count: 300_000)
        + Data("b".utf8) + Data(repeating: UInt8(ascii: "a"), count: 1000)
}

@Suite("Zstd decoder — reference-encoder fixtures")
struct ZstdFixtureTests {
    @Test(
        "every rollout variant decodes to its plain twin",
        arguments: [
            "rollout.jsonl.zst", "rollout.l1.jsonl.zst", "rollout.l19.jsonl.zst",
            "rollout.raw-literals.jsonl.zst", "rollout.long27.jsonl.zst",
        ])
    func rolloutVariants(name: String) throws {
        let plain = try ZstdFixture.data("rollout.jsonl")
        let (output, stats) = try ZstdFixture.decode(ZstdFixture.data(name))
        #expect(output == plain)
        #expect(stats.frames == 1)
        #expect(stats.compressedBlocks >= 2, "the fixture must span more than one block")
    }

    @Test(
        "every tiny variant decodes to its plain twin",
        arguments: ["tiny.jsonl.zst", "tiny.no-check.jsonl.zst", "tiny.wlog10.jsonl.zst"])
    func tinyVariants(name: String) throws {
        let plain = try ZstdFixture.data("tiny.jsonl")
        #expect(try ZstdFixture.decode(ZstdFixture.data(name)).output == plain)
    }

    @Test("several frames and a skippable frame decode in sequence")
    func multiFrame() throws {
        let plain = try ZstdFixture.data("tiny.jsonl")
        let (output, stats) = try ZstdFixture.decode(ZstdFixture.data("multi-frame.zst"))
        #expect(output == plain + plain)
        #expect(stats.frames == 2)
        #expect(stats.skippableFrames == 1)
        #expect(stats.checksumsVerified == 1)
    }

    @Test("incompressible bytes arrive as raw blocks")
    func noise() throws {
        let (output, stats) = try ZstdFixture.decode(ZstdFixture.data("noise.bin.zst"))
        #expect(output == ZstdFixture.noise(count: 20000, seed: 99))
        #expect(stats.rawBlocks >= 1)
        #expect(stats.checksumsVerified == 1)
    }

    @Test("patterns the encoder codes with RLE literals and RLE tables")
    func patterns() throws {
        let ab = try ZstdFixture.decode(ZstdFixture.data("pattern-ab.bin.zst"))
        #expect(ab.output == ZstdFixture.pattern("ab"))
        #expect(ab.stats.rleLiterals >= 1)
        let z = try ZstdFixture.decode(ZstdFixture.data("pattern-z.bin.zst"))
        #expect(z.output == ZstdFixture.pattern("z"))
        #expect(z.stats.rleTables >= 1)
    }

    @Test("a long run arrives as RLE blocks")
    func runs() throws {
        let (output, stats) = try ZstdFixture.decode(ZstdFixture.data("runs.bin.zst"))
        #expect(output == ZstdFixture.runs)
        #expect(stats.rleBlocks >= 1)
    }
}

@Suite("Zstd decoder — path coverage")
struct ZstdCoverageTests {
    /// Every branch of the format the decoder implements is reached by at
    /// least one fixture. An unhit path means a missing fixture — never a
    /// dropped assertion.
    @Test("the fixtures reach every decoding path")
    func everyPathIsExercised() throws {
        let names = [
            "rollout.jsonl.zst", "rollout.l1.jsonl.zst", "rollout.l19.jsonl.zst",
            "rollout.raw-literals.jsonl.zst", "rollout.long27.jsonl.zst", "tiny.jsonl.zst",
            "tiny.no-check.jsonl.zst", "tiny.wlog10.jsonl.zst", "multi-frame.zst",
            "noise.bin.zst", "runs.bin.zst", "pattern-ab.bin.zst", "pattern-z.bin.zst",
        ]
        var total = ZstdStats()
        let slack = ZstdLimits(windowSlack: 64)
        for name in names {
            let stats = try ZstdFixture.decode(ZstdFixture.data(name), limits: slack).stats
            for path in Self.paths { total[keyPath: path] += stats[keyPath: path] }
        }
        for (path, name) in zip(Self.paths, Self.names) {
            #expect(total[keyPath: path] > 0, "no fixture reaches \(name)")
        }
    }

    private static var paths: [WritableKeyPath<ZstdStats, Int>] { [
        \.frames, \.skippableFrames, \.windowDescriptors, \.checksumsVerified, \.rawBlocks,
        \.rleBlocks, \.compressedBlocks, \.rawLiterals, \.rleLiterals, \.huffmanLiterals1Stream,
        \.huffmanLiterals4Streams, \.treelessLiterals, \.predefinedTables, \.rleTables,
        \.fseTables, \.repeatTables, \.repeatOffsets, \.compactions,
    ] }
    private static let names = [
        "frames", "skippableFrames", "windowDescriptors", "checksumsVerified", "rawBlocks",
        "rleBlocks", "compressedBlocks", "rawLiterals", "rleLiterals", "huffmanLiterals1Stream",
        "huffmanLiterals4Streams", "treelessLiterals", "predefinedTables", "rleTables",
        "fseTables", "repeatTables", "repeatOffsets", "compactions",
    ]

    @Test("a tiny window compacts without changing the output")
    func compactionKeepsOutput() throws {
        let plain = try ZstdFixture.data("tiny.jsonl")
        let (output, stats) = try ZstdFixture.decode(
            ZstdFixture.data("tiny.wlog10.jsonl.zst"), limits: ZstdLimits(windowSlack: 1))
        #expect(output == plain)
        #expect(stats.compactions > 0)
    }
}

/// Hand-built frames, each checked against `zstd -d` (1.5.7) when written:
/// the expected output, or that the reference refuses it too.
enum ZstdFrameBuilder {
    /// A backward bitstream holding `fields` (value, bit count) in DECODE
    /// order, closed by its end marker.
    static func bitstream(_ fields: [(UInt64, Int)]) -> [UInt8] {
        var accumulator: UInt64 = 0
        var bits = 0
        for (value, count) in fields.reversed() {
            accumulator |= value << UInt64(bits)
            bits += count
        }
        accumulator |= 1 << UInt64(bits)
        bits += 1
        return (0..<((bits + 7) / 8)).map { UInt8(truncatingIfNeeded: accumulator >> UInt64(8 * $0)) }
    }

    static func rawLiterals(_ text: String) -> [UInt8] {
        [UInt8(text.utf8.count << 3)] + Array(text.utf8)
    }

    /// A compressed block of raw literals and sequences in RLE mode: every
    /// sequence uses literal-length code `ll`, offset code `of`, match code `ml`.
    static func rleSequences(
        literals: String, ll: UInt8, of: UInt8, ml: UInt8, count: UInt8 = 1,
        bits: [(UInt64, Int)] = []
    ) -> [UInt8] {
        rawLiterals(literals) + [count, 0x54, ll, of, ml] + bitstream(bits)
    }

    static func block(_ content: [UInt8], last: Bool, type: Int = 2, size: Int? = nil) -> [UInt8] {
        let header = (last ? 1 : 0) | type << 1 | (size ?? content.count) << 3
        return [UInt8(header & 0xFF), UInt8((header >> 8) & 0xFF), UInt8(header >> 16)] + content
    }

    static let magic: [UInt8] = [0x28, 0xB5, 0x2F, 0xFD]

    /// No content size, a 1 KiB window descriptor, no checksum.
    static func frame(_ blocks: [[UInt8]]) -> Data {
        Data(magic + [0x00, 0x00] + blocks.joined())
    }

    /// literals "abcdefgh", then copy 3 from offset 8 → "abcdefghabc";
    /// repeat offsets become (8, 1, 4).
    static let primer = block(
        rleSequences(literals: "abcdefgh", ll: 8, of: 3, ml: 0, bits: [(3, 3)]), last: false)
}

@Suite("Zstd decoder — sequence semantics")
struct ZstdSequenceSemanticsTests {
    typealias B = ZstdFrameBuilder

    @Test("repeat offsets, including the literal-length-zero shift")
    func repeatOffsets() throws {
        // LL 0, Offset_Value 1 → the SECOND repeat offset (1).
        let shift1 = B.frame([B.primer, B.block(B.rleSequences(literals: "", ll: 0, of: 0, ml: 1), last: true)])
        #expect(try ZstdDecoder.decompress(shift1) == Data("abcdefghabccccc".utf8))
        // LL 0, Offset_Value 2 → the THIRD (4).
        let shift2 = B.frame([
            B.primer, B.block(B.rleSequences(literals: "", ll: 0, of: 1, ml: 0, bits: [(0, 1)]), last: true),
        ])
        #expect(try ZstdDecoder.decompress(shift2) == Data("abcdefghabchab".utf8))
        // LL 0, Offset_Value 3 → the first minus one (7).
        let shift3 = B.frame([
            B.primer, B.block(B.rleSequences(literals: "", ll: 0, of: 1, ml: 0, bits: [(1, 1)]), last: true),
        ])
        #expect(try ZstdDecoder.decompress(shift3) == Data("abcdefghabcefg".utf8))
        // LL > 0, Offset_Value 1 → the first repeat offset (8), twice in one block.
        let twoSequences = B.frame([
            B.primer,
            B.block(B.rawLiterals("wxyz1234") + [2, 0x54, 4, 0, 0] + B.bitstream([]), last: true),
        ])
        #expect(try ZstdDecoder.decompress(twoSequences) == Data("abcdefghabcwxyzhab1234zha".utf8))
    }

    @Test("a repeat offset of zero is refused")
    func repeatOffsetZero() {
        // First block: repeat offsets (1, 4, 8); LL 0 + Offset_Value 3 → 1 − 1.
        let frame = B.frame([B.block(B.rleSequences(literals: "", ll: 0, of: 1, ml: 0, bits: [(1, 1)]), last: true)])
        #expect(throws: ZstdError.corrupt("repeat offset of zero")) { try ZstdDecoder.decompress(frame) }
    }

    @Test("a match reaching before the frame's start is refused")
    func offsetBeyondHistory() {
        let frame = B.frame([B.block(B.rleSequences(literals: "", ll: 0, of: 0, ml: 0), last: true)])
        #expect(throws: ZstdError.corrupt("match offset beyond the window")) {
            try ZstdDecoder.decompress(frame)
        }
    }

    @Test("a sequence wanting more literals than the block holds is refused")
    func literalsOverrun() {
        let frame = B.frame([B.block(B.rleSequences(literals: "abcdefgh", ll: 9, of: 3, ml: 0, bits: [(3, 3)]), last: true)])
        #expect(throws: ZstdError.corrupt("sequence needs more literals than the block holds")) {
            try ZstdDecoder.decompress(frame)
        }
    }

    @Test("a bitstream with bits left over is refused")
    func bitstreamLeftover() {
        let frame = B.frame([B.block(B.rleSequences(literals: "ab", ll: 2, of: 0, ml: 0, bits: [(1, 3)]), last: true)])
        #expect(throws: ZstdError.self) { try ZstdDecoder.decompress(frame) }
    }

    @Test("the predefined tables build from the RFC's distributions")
    func predefinedTables() {
        #expect(ZstdTables.predefinedLiteralLengths.accuracyLog == 6)
        #expect(ZstdTables.predefinedMatchLengths.accuracyLog == 6)
        #expect(ZstdTables.predefinedOffsets.accuracyLog == 5)
        #expect(Set(ZstdTables.predefinedLiteralLengths.symbols).count == 36)
        #expect(Set(ZstdTables.predefinedMatchLengths.symbols).count == 53)
        #expect(Set(ZstdTables.predefinedOffsets.symbols).count == 29)
        #expect(ZstdTables.literalLengthBase.count == 36 && ZstdTables.literalLengthBits.count == 36)
        #expect(ZstdTables.matchLengthBase.count == 53 && ZstdTables.matchLengthBits.count == 53)
    }
}

@Suite("Zstd decoder — hostile and malformed input")
struct ZstdMalformedTests {
    typealias B = ZstdFrameBuilder

    /// Single-segment header for a frame of `size` bytes (< 256).
    private static func singleSegment(_ size: UInt8, checksum: Bool = false) -> [UInt8] {
        B.magic + [checksum ? 0x24 : 0x20, size]
    }

    @Test("header refusals: magic, reserved bit, dictionary, window, sizes")
    func headerRefusals() throws {
        #expect(throws: ZstdError.truncated) { try ZstdDecoder.decompress(Data()) }
        #expect(throws: ZstdError.notZstd) { try ZstdDecoder.decompress(Data("{\"not\":\"zstd\"}".utf8)) }
        #expect(throws: ZstdError.corrupt("reserved frame header bit set")) {
            try ZstdDecoder.decompress(Data(B.magic + [0x28, 0x00]))
        }
        // Dictionary ID 7 in a one-byte field.
        #expect(throws: ZstdError.dictionaryRequired) {
            try ZstdDecoder.decompress(Data(B.magic + [0x21, 0x07, 0x00]))
        }
        // A zero dictionary ID means "none" — that frame decodes.
        let noDictionary = Data(B.magic + [0x21, 0x00, 0x02] + B.block(Array("hi".utf8), last: true, type: 0))
        #expect(try ZstdDecoder.decompress(noDictionary) == Data("hi".utf8))
        // Window descriptor 2^41.
        #expect(throws: ZstdError.windowTooLarge) { try ZstdDecoder.decompress(Data(B.magic + [0x00, 0xF8])) }
        // Single segment of 200 MiB: its window is the content size.
        let huge = withUnsafeBytes(of: UInt64(200 << 20).littleEndian, Array.init)
        #expect(throws: ZstdError.windowTooLarge) { try ZstdDecoder.decompress(Data(B.magic + [0xE0] + huge)) }
        // A stated size past the output limit.
        let tooBig = withUnsafeBytes(of: UInt64(2 << 30).littleEndian, Array.init)
        #expect(throws: ZstdError.outputTooLarge) { try ZstdDecoder.decompress(Data(B.magic + [0xE0] + tooBig)) }
        // A real encoder's 2^28 window (`zstd --long=28`), one past the limit.
        #expect(throws: ZstdError.windowTooLarge) {
            try ZstdDecoder.decompress(ZstdFixture.data("tiny.long28.jsonl.zst"))
        }
        // The limit is the limit: a 2^27 window decodes, a lower cap refuses it.
        #expect(throws: ZstdError.windowTooLarge) {
            try ZstdDecoder.decompress(
                ZstdFixture.data("rollout.long27.jsonl.zst"), limits: ZstdLimits(maxWindowSize: 1 << 26))
        }
    }

    @Test("block refusals: reserved type, oversized blocks")
    func blockRefusals() {
        #expect(throws: ZstdError.corrupt("reserved block type")) {
            try ZstdDecoder.decompress(B.frame([B.block([], last: true, type: 3)]))
        }
        // A raw block bigger than the 1 KiB window allows.
        #expect(throws: ZstdError.corrupt("block larger than its maximum size")) {
            try ZstdDecoder.decompress(B.frame([B.block([UInt8](repeating: 1, count: 1025), last: true, type: 0)]))
        }
        // An RLE block past 128 KiB, in a frame whose window allows more.
        #expect(throws: ZstdError.corrupt("block larger than its maximum size")) {
            try ZstdDecoder.decompress(Data(B.magic + [0x00, 0x58] + B.block([7], last: true, type: 1, size: 131_073)))
        }
        // A block decoding past the block maximum: 8 literals + a 3-byte match
        // in a frame whose window (and so block maximum) is 9.
        let tight = Data(Self.singleSegment(9) + B.block(
            B.rleSequences(literals: "abcdefgh", ll: 8, of: 3, ml: 0, bits: [(3, 3)]), last: true))
        #expect(throws: ZstdError.self) { try ZstdDecoder.decompress(tight) }
    }

    @Test("a content size that lies, either way, is refused")
    func lyingContentSize() throws {
        // Four-byte content size, 1 KiB window, one raw block "abcd".
        func frame(stating size: UInt8) -> Data {
            Data(B.magic + [0x80, 0x00, size, 0, 0, 0] + B.block(Array("abcd".utf8), last: true, type: 0))
        }
        #expect(throws: ZstdError.contentSizeMismatch) { try ZstdDecoder.decompress(frame(stating: 3)) }
        #expect(throws: ZstdError.contentSizeMismatch) { try ZstdDecoder.decompress(frame(stating: 5)) }
        #expect(try ZstdDecoder.decompress(frame(stating: 4)) == Data("abcd".utf8))
    }

    @Test("a wrong checksum is refused")
    func checksumMismatch() throws {
        var data = try ZstdFixture.data("tiny.jsonl.zst")
        data[data.count - 1] ^= 0x01
        #expect(throws: ZstdError.checksumMismatch) { try ZstdDecoder.decompress(data) }
    }

    @Test("table refusals: FSE accuracy, FSE symbols, Huffman weights, missing repeats")
    func tableRefusals() {
        // Literal-length table in FSE mode with accuracy log 5 + 15.
        let accuracy = B.frame([B.block([0x00, 0x01, 0x80, 0x0F, 0xFF, 0xFF], last: true)])
        #expect(throws: ZstdError.corrupt("FSE accuracy log too large")) { try ZstdDecoder.decompress(accuracy) }
        // Offset table: a zero probability, then "three more zeros" forever.
        let symbols = B.frame([B.block([0x00, 0x01, 0x20, 0x10, 0xFE, 0xFF, 0xFF, 0xFF, 0xFF, 0x01], last: true)])
        #expect(throws: ZstdError.corrupt("FSE symbol out of range")) { try ZstdDecoder.decompress(symbols) }
        // Repeat mode in a frame's first compressed block.
        let repeatMode = B.frame([B.block([0x00, 0x01, 0xFC, 0x01], last: true)])
        #expect(throws: ZstdError.corrupt("repeat mode with no previous table")) { try ZstdDecoder.decompress(repeatMode) }
        // An RLE literal-length symbol past code 35.
        let rleSymbol = B.frame([B.block([0x00, 0x01, 0x54, 36, 0, 0, 0x01], last: true)])
        #expect(throws: ZstdError.corrupt("RLE sequence symbol out of range")) { try ZstdDecoder.decompress(rleSymbol) }
        // Reserved bits in the modes byte.
        let reserved = B.frame([B.block([0x00, 0x01, 0x01, 0x01], last: true)])
        #expect(throws: ZstdError.corrupt("reserved bits set in sequence modes")) { try ZstdDecoder.decompress(reserved) }
        // Treeless literals with no previous Huffman table: type 3, one stream,
        // 4 literals in 2 bytes.
        let treeless = B.frame([B.block([0x43, 0x80, 0x00, 0x01, 0x01, 0x00], last: true)])
        #expect(throws: ZstdError.corrupt("treeless literals with no previous table")) {
            try ZstdDecoder.decompress(treeless)
        }
        // Huffman weights 3 and 1 (direct): 5 points leave 3 — no power of two.
        let weights = B.frame([B.block([0x42, 0xC0, 0x00, 0x81, 0x31, 0x01, 0x00], last: true)])
        #expect(throws: ZstdError.corrupt("Huffman weights don't complete a tree")) { try ZstdDecoder.decompress(weights) }
        // No sequences, but bytes after the count.
        let trailing = B.frame([B.block([0x00, 0x00, 0xAA], last: true)])
        #expect(throws: ZstdError.corrupt("bytes after an empty sequences section")) { try ZstdDecoder.decompress(trailing) }
    }

    private static func hex(_ text: String) -> Data {
        var bytes: [UInt8] = []
        var index = text.startIndex
        while index < text.endIndex {
            let next = text.index(index, offsetBy: 2)
            bytes.append(UInt8(text[index..<next], radix: 16) ?? 0)
            index = next
        }
        return Data(bytes)
    }

    /// Both refused by `zstd -d` 1.5.7 ("Data corruption detected" /
    /// "Literals' block doesn't respect format specification"); found by the
    /// review's differential fuzz, where this decoder had accepted them.
    @Test("shapes the reference refuses: a tree without a weight-1 pair, four streams under 6 literals")
    func referenceRefusals() {
        #expect(throws: ZstdError.corrupt("Huffman tree without a weight-1 pair")) {
            try ZstdDecoder.decompress(Self.hex("28b52ffd0000450000820001802069010" + "0"))
        }
        for frame in [
            "28b52ffd000085000006000380100100010001000101010100",
            "28b52ffd000085000036000380100100010001000303030100",
            "28b52ffd000085000046000380100100010001000303030300",
        ] {
            #expect(throws: ZstdError.corrupt("too few literals for four streams")) {
                try ZstdDecoder.decompress(Self.hex(frame))
            }
        }
    }

    @Test("trailing bytes after the last frame are refused")
    func trailingGarbage() throws {
        let tiny = try ZstdFixture.data("tiny.jsonl.zst")
        #expect(throws: ZstdError.truncated) { try ZstdDecoder.decompress(tiny + Data([1, 2])) }
        #expect(throws: ZstdError.notZstd) { try ZstdDecoder.decompress(tiny + Data([1, 2, 3, 4])) }
        // A skippable frame claiming more bytes than exist.
        #expect(throws: ZstdError.truncated) { try ZstdDecoder.decompress(tiny + Data([0x50, 0x2A, 0x4D, 0x18, 9, 0, 0, 0, 1])) }
    }

    @Test("the output limit stops a stream mid-way")
    func outputLimit() throws {
        // Stated size past the limit: refused at the header.
        #expect(throws: ZstdError.outputTooLarge) {
            try ZstdDecoder.decompress(ZstdFixture.data("tiny.jsonl.zst"), limits: ZstdLimits(maxOutputSize: 1000))
        }
        // No stated size (a pipe): refused once the output passes the limit.
        #expect(throws: ZstdError.outputTooLarge) {
            try ZstdDecoder.decompress(ZstdFixture.data("runs.bin.zst"), limits: ZstdLimits(maxOutputSize: 100_000))
        }
    }

    @Test("a failed stream stays failed")
    func stickyFailure() throws {
        var data = try ZstdFixture.data("multi-frame.zst")
        data[40] ^= 0xFF
        var decoder = ZstdDecoder(source: ByteSource(data: data))
        var first: ZstdError?
        while first == nil {
            do throws(ZstdError) {
                guard try decoder.next() != nil else { break }
            } catch {
                first = error
            }
        }
        let failure = try #require(first)
        #expect(throws: failure) { try decoder.next() }
    }

    @Test("every truncation of a checksummed frame is an error")
    func everyTruncation() throws {
        for name in ["tiny.jsonl.zst", "tiny.no-check.jsonl.zst"] {
            let data = try ZstdFixture.data(name)
            for length in 0..<data.count {
                #expect(throws: ZstdError.self, "\(name) cut at \(length)") {
                    try ZstdDecoder.decompress(data.prefix(length))
                }
            }
        }
    }

    @Test("sampled truncations of a multi-block frame are errors")
    func sampledTruncations() throws {
        let data = try ZstdFixture.data("rollout.jsonl.zst")
        for length in stride(from: 0, to: data.count, by: 211) {
            #expect(throws: ZstdError.self, "cut at \(length)") { try ZstdDecoder.decompress(data.prefix(length)) }
        }
    }

    /// Every bit of the first 256 bytes — the headers and table
    /// descriptions, where a flip changes structure — then every fifth.
    private static func flipPositions(_ count: Int) -> [Int] {
        Array(0..<min(count * 8, 2048)) + Array(stride(from: 2048, to: count * 8, by: 5))
    }

    @Test("single-bit flips of a checksummed frame: an error, or the same bytes")
    func bitFlips() throws {
        let data = try ZstdFixture.data("tiny.jsonl.zst")
        let plain = try ZstdFixture.data("tiny.jsonl")
        var accepted = 0
        for bit in Self.flipPositions(data.count) {
            var flipped = data
            flipped[bit / 8] ^= 1 << UInt8(bit % 8)
            if let output = try? ZstdDecoder.decompress(flipped) {
                #expect(output == plain, "bit \(bit) decoded to other bytes past the checksum")
                accepted += 1
            }
        }
        // Only header bits that don't change the content (e.g. a larger
        // window) may pass.
        #expect(accepted < 16)
    }

    @Test("bit flips without a checksum always return, within the limits")
    func bitFlipsWithoutChecksum() throws {
        let data = try ZstdFixture.data("tiny.no-check.jsonl.zst")
        let limits = ZstdLimits(maxOutputSize: 1 << 20)
        for bit in Self.flipPositions(data.count) {
            var flipped = data
            flipped[bit / 8] ^= 1 << UInt8(bit % 8)
            if let output = try? ZstdDecoder.decompress(flipped, limits: limits) {
                #expect(output.count <= 1 << 20)
            }
        }
        let rollout = try ZstdFixture.data("rollout.l1.jsonl.zst")
        let rolloutPlain = try ZstdFixture.data("rollout.jsonl")
        for bit in stride(from: 0, to: rollout.count * 8, by: 8009) {
            var flipped = rollout
            flipped[bit / 8] ^= 1 << UInt8(bit % 8)
            if let output = try? ZstdDecoder.decompress(flipped) {
                #expect(output == rolloutPlain, "bit \(bit) decoded to other bytes past the checksum")
            }
        }
    }
}

@Suite("XXH64")
struct XXHash64Tests {
    private static func hash(_ text: String) -> UInt64 {
        var hasher = XXHash64()
        hasher.update(Array(text.utf8))
        return hasher.digest()
    }

    @Test("reference vectors")
    func vectors() {
        #expect(Self.hash("") == 0xEF46_DB37_51D8_E999)
        #expect(Self.hash("a") == 0xD24E_C4F1_A98C_6E5B)
        #expect(Self.hash("abc") == 0x44BC_2CF5_AD77_0999)
    }

    @Test("streaming in any chunking equals one shot")
    func chunking() {
        let bytes = Array(ZstdFixture.noise(count: 1000, seed: 3))
        var whole = XXHash64()
        whole.update(bytes)
        for chunk in [1, 7, 31, 32, 33, 100] {
            var hasher = XXHash64()
            for start in stride(from: 0, to: bytes.count, by: chunk) {
                hasher.update(Array(bytes[start..<min(start + chunk, bytes.count)]))
            }
            #expect(hasher.digest() == whole.digest(), "chunk \(chunk)")
        }
    }
}
